      --panel: rgba(17, 24, 39, 0.9);
      --panel-strong: rgba(30, 41, 59, 0.95);
      --border: rgba(148, 163, 184, 0.2);
      --text: #e5eefb;
      --muted: #9fb0c8;
      --accent: #7dd3fc;
      --accent-strong: #38bdf8;
      --shadow: 0 20px 45px rgba(2, 6, 23, 0.45);
    }

