      margin: 0 0 10px;
      font-size: clamp(2rem, 4vw, 3rem);
      line-height: 1.1;
    }

    .hero p {
      margin: 0;
      max-width: 60ch;
      color: var(--muted);
      line-height: 1.6;
    }

    .faq {
      padding: 24px;
    }

